/* MP227 — Asisten AI (2.2.8: kontras WCAG AA, latar solid, tema gelap konsisten, kartu agen & analisis · 2.2.9: perintah cepat 2 kolom, tombol coba lagi) */
.mp227-fab { position: fixed; right: 18px; bottom: 18px; z-index: 1040; display: inline-flex; align-items: center; gap: 8px; border: 0; border-radius: 999px; padding: 11px 16px 11px 14px;
  background: linear-gradient(135deg, #0B1F3A, #1763B3); color: #fff; font-weight: 600; font-size: .86rem; box-shadow: 0 8px 22px rgba(11, 31, 58, .32); text-shadow: none; }
.mp227-fab:hover { background: linear-gradient(135deg, #123059, #1F78D1); }
.mp227-fab:focus-visible { outline: 3px solid #7DB6F2; outline-offset: 2px; }
.mp227-fab i { font-size: 1rem; }
@media (max-width: 991.98px) { .mp227-fab { bottom: 78px; right: 12px; padding: 12px; } .mp227-fab span { display: none; } }
/* token warna lokal panel: terang (bawaan) */
.mp227-ai { --f-kartu: #FFFFFF; --f-garis: #D3DBE6; --ai-latar: #F4F6FA; --ai-teks: #0B1F3A; --ai-redup: #44546B; --ai-aksen: #1763B3; --ai-aksen-tk: #FFFFFF; --ai-kode: #E8EEF7;
  --ai-galat-bg: #FDECEC; --ai-galat-gr: #E7A6AA; --ai-galat-tk: #8A1A20; --ai-ok-bg: #E8F6EE; --ai-ok-tk: #17673A; --ai-warn-bg: #FFF4E0; --ai-warn-tk: #7A4A00; }
/* tema gelap: kartu & garis tetap lewat --f-kartu / --f-garis */
html[data-tema="gelap"] .mp227-ai, [data-bs-theme="dark"] .mp227-ai { --f-kartu: #13253B; --f-garis: #2B4260; --ai-latar: #0D1B2C; --ai-teks: #E8EEF7; --ai-redup: #B4C2D4; --ai-aksen: #7DB6F2; --ai-aksen-tk: #0B1F3A; --ai-kode: #1D3350;
  --ai-galat-bg: #3A1518; --ai-galat-gr: #7A2A30; --ai-galat-tk: #FFC9CC; --ai-ok-bg: #12301F; --ai-ok-tk: #9FE0B8; --ai-warn-bg: #33270F; --ai-warn-tk: #FFD991; }
.mp227-ai { position: fixed; right: 18px; bottom: 18px; z-index: 1045; width: min(480px, calc(100vw - 24px)); height: min(700px, calc(100vh - 36px)); display: flex; flex-direction: column;
  background: var(--f-kartu, #fff); color: var(--ai-teks); border: 1px solid var(--f-garis, #D3DBE6); border-radius: 14px; box-shadow: 0 18px 50px rgba(11, 31, 58, .28); overflow: hidden;
  opacity: 1; filter: none; mix-blend-mode: normal; backdrop-filter: none; -webkit-backdrop-filter: none; text-shadow: none; isolation: isolate; }
.mp227-ai *, .mp227-ai *::before, .mp227-ai *::after { text-shadow: none; }
@media (max-width: 991.98px) { .mp227-ai { right: 8px; left: 8px; width: auto; bottom: 70px; height: calc(100vh - 90px); } }
/* header navy → putih */
.mp227-ai-h { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 10px 12px; background: #0B1F3A; color: #FFFFFF; flex: none; }
.mp227-ai-h .t { display: flex; align-items: center; gap: 9px; min-width: 0; }
.mp227-ai-h b { color: #FFFFFF; }
.mp227-ai-h .ik { width: 32px; height: 32px; border-radius: 9px; display: grid; place-items: center; background: linear-gradient(135deg, #1763B3, #E3343F); flex: none; }
.mp227-ai-h small { display: block; opacity: 1; color: #C9D6E8; font-size: .7rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 200px; }
.mp227-ai-h .a { display: flex; align-items: center; gap: 4px; flex: none; }
.mp227-agen { display: inline-block; margin-left: 4px; padding: 0 6px; border-radius: 999px; background: #E3343F; color: #FFFFFF; font-size: .62rem; font-weight: 700; vertical-align: 2px; text-transform: uppercase; letter-spacing: .03em; }
.mp227-sel { box-sizing: border-box; font: inherit; max-width: 132px; border: 1px solid #5C7899; background: #0B1F3A; color: #FFFFFF; font-size: .74rem; padding: 3px 6px; border-radius: 6px; }
.mp227-sel option { background: #FFFFFF; color: #0B1F3A; }
.mp227-sel:focus-visible, .mp227-ic:focus-visible { outline: 2px solid #7DB6F2; outline-offset: 1px; }
.mp227-seg { border: 1px solid #5C7899; background: transparent; color: #fff; font-size: .72rem; padding: 3px 8px; border-radius: 6px; }
.mp227-seg.on { background: #fff; color: #0B1F3A; font-weight: 700; }
.mp227-seg:disabled { color: #8FA3BC; border-color: #34506F; }
.mp227-ic { border: 0; background: transparent; color: #FFFFFF; width: 28px; height: 28px; border-radius: 6px; }
.mp227-ic:hover { background: #1D3A60; }
/* perintah cepat */
.mp227-pc { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; padding: 7px 10px 8px; background: var(--f-kartu, #fff); border-bottom: 1px solid var(--f-garis, #D3DBE6); flex: none; overflow: hidden; }
.mp227-pc > span { grid-column: 1 / -1; font-size: .7rem; font-weight: 700; color: var(--ai-redup); white-space: nowrap; }
.mp227-pc > span em { font-style: normal; font-weight: 600; color: var(--ai-warn-tk); }
.mp227-pc button { display: flex; align-items: center; gap: 6px; min-width: 0; border: 1px solid var(--f-garis, #D3DBE6); background: var(--ai-latar); color: var(--ai-teks); border-radius: 8px; padding: 4px 8px; font-size: .72rem; line-height: 1.25; text-align: left; }
.mp227-pc button > span { overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.mp227-pc button i { flex: none; }
@media (max-width: 420px) { .mp227-pc { grid-template-columns: 1fr; } }
.mp227-pc button:hover:not(:disabled) { border-color: var(--ai-aksen); }
.mp227-pc button:disabled { color: var(--ai-redup); cursor: not-allowed; }
.mp227-pc button i { color: var(--ai-aksen); }
/* badan pesan: teks gelap #0B1F3A di #F4F6FA (≈15:1) */
.mp227-ai-b { flex: 1; overflow: auto; padding: 12px; background: var(--ai-latar); color: var(--ai-teks); display: flex; flex-direction: column; gap: 10px; opacity: 1; filter: none; mix-blend-mode: normal; }
.mp227-msg { display: flex; opacity: 1; filter: none; mix-blend-mode: normal; }
.mp227-msg.u { justify-content: flex-end; }
.mp227-msg.u > div { background: #1763B3; color: #FFFFFF; padding: 8px 12px; border-radius: 12px 12px 3px 12px; max-width: 85%; font-size: .86rem; line-height: 1.45; white-space: normal; word-break: break-word; }
.mp227-msg.ai > div { background: var(--f-kartu, #fff); color: var(--ai-teks); border: 1px solid var(--f-garis, #D3DBE6); padding: 9px 12px; border-radius: 12px 12px 12px 3px; max-width: 94%; font-size: .85rem; line-height: 1.5; word-break: break-word; }
.mp227-msg.ai.an > div { max-width: 100%; width: 100%; }
.mp227-msg.ai.galat > div { border-color: var(--ai-galat-gr); background: var(--ai-galat-bg); color: var(--ai-galat-tk); overflow-wrap: anywhere; }
.mp227-ul { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.mp227-ul button { border: 1px solid var(--ai-galat-gr); background: var(--f-kartu, #fff); color: var(--ai-teks); border-radius: 7px; padding: 3px 9px; font-size: .74rem; }
.mp227-ul button:hover { border-color: var(--ai-aksen); }
.mp227-cd { margin-top: 6px; font-size: .72rem; color: var(--ai-warn-tk); background: var(--ai-warn-bg); border-radius: 6px; padding: 3px 7px; }
.mp227-msg .isi { color: var(--ai-teks); }
.mp227-msg .isi p { margin: 0 0 6px; } .mp227-msg .isi ul, .mp227-msg .isi ol { margin: 0 0 6px; padding-left: 18px; } .mp227-msg .isi h6 { margin: 8px 0 4px; font-weight: 700; color: var(--ai-teks); }
.mp227-msg .isi a, .mp227-ai-b a { color: var(--ai-aksen); text-decoration: underline; }
.mp227-msg .isi pre, .mp227-pre { background: #0B1F3A; color: #E8EEF7; padding: 8px; border-radius: 7px; font-size: .74rem; white-space: pre-wrap; word-break: break-word; margin: 4px 0 6px; max-height: 260px; overflow: auto; }
.mp227-msg .isi code, .mp227-ai-b code { background: var(--ai-kode); color: var(--ai-teks); padding: 0 3px; border-radius: 3px; }
.mp227-tw { overflow: auto; margin: 4px 0 8px; } .mp227-tw table { border-collapse: collapse; font-size: .76rem; color: var(--ai-teks); } .mp227-tw th, .mp227-tw td { border: 1px solid var(--f-garis, #D3DBE6); padding: 3px 6px; } .mp227-tw th { background: var(--ai-latar); font-weight: 700; }
.mp227-msg .kaki { display: flex; justify-content: space-between; align-items: center; gap: 8px; margin-top: 6px; padding-top: 5px; border-top: 1px dashed var(--f-garis, #D3DBE6); font-size: .7rem; color: var(--ai-redup); }
.mp227-msg .kaki button { border: 0; background: transparent; color: var(--ai-aksen); font-size: .72rem; }
.mp227-ai-kosong { margin: auto 0; text-align: center; color: var(--ai-redup); font-size: .85rem; }
.mp227-ai-kosong > i { font-size: 1.8rem; color: var(--ai-aksen); }
.mp227-saran { display: grid; gap: 6px; margin-top: 10px; text-align: left; }
.mp227-saran button { border: 1px solid var(--f-garis, #D3DBE6); background: var(--f-kartu, #fff); border-radius: 9px; padding: 7px 10px; font-size: .8rem; color: var(--ai-teks); display: flex; gap: 8px; align-items: center; }
.mp227-saran button:hover { border-color: var(--ai-aksen); }
.mp227-saran i { color: var(--ai-aksen); width: 16px; }
/* langkah agen, usulan, analisis, saran */
.mp227-lk { display: flex; flex-wrap: wrap; gap: 4px; margin-bottom: 6px; }
.mp227-lk span { display: inline-flex; align-items: center; gap: 5px; font-size: .68rem; padding: 1px 7px; border-radius: 999px; border: 1px solid var(--f-garis, #D3DBE6); background: var(--ai-latar); color: var(--ai-redup); }
.mp227-lk span.gagal { background: var(--ai-galat-bg); color: var(--ai-galat-tk); border-color: var(--ai-galat-gr); }
.mp227-us { margin-top: 8px; border: 1px solid var(--f-garis, #D3DBE6); border-left: 4px solid #F28C28; border-radius: 9px; padding: 8px 10px; background: var(--ai-latar); color: var(--ai-teks); font-size: .8rem; }
.mp227-us.diterapkan { border-left-color: #2E9E5B; } .mp227-us.dibatalkan { border-left-color: #8794A6; }
.mp227-us .h { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; } .mp227-us .h > i { color: #C26A12; }
.mp227-us .al { margin-top: 4px; color: var(--ai-redup); }
.mp227-us .pr { margin-top: 6px; padding: 6px 8px; border-radius: 7px; background: var(--f-kartu, #fff); border: 1px dashed var(--f-garis, #D3DBE6); }
.mp227-us .pr > span { display: block; font-size: .68rem; font-weight: 700; color: var(--ai-redup); text-transform: uppercase; letter-spacing: .03em; margin-bottom: 2px; }
.mp227-us .gl, .mp227-ai-b .gl { color: var(--ai-galat-tk); background: var(--ai-galat-bg); border-radius: 6px; padding: 3px 6px; margin-top: 4px; }
.mp227-us .pw { color: var(--ai-warn-tk); background: var(--ai-warn-bg); border-radius: 6px; padding: 3px 6px; margin-top: 4px; }
.mp227-us .hs { color: var(--ai-ok-tk); background: var(--ai-ok-bg); border-radius: 6px; padding: 3px 6px; margin-top: 6px; }
.mp227-us details { margin-top: 5px; } .mp227-us summary { cursor: pointer; color: var(--ai-aksen); font-size: .74rem; }
.mp227-us .b, .mp227-sr .b { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; margin-top: 7px; }
.mp227-us .b small, .mp227-sr .b small { color: var(--ai-redup); }
.mp227-st { display: inline-block; margin-left: auto; font-size: .66rem; font-weight: 700; padding: 1px 7px; border-radius: 999px; background: var(--ai-warn-bg); color: var(--ai-warn-tk); }
.mp227-st.diterapkan { background: var(--ai-ok-bg); color: var(--ai-ok-tk); } .mp227-st.dibatalkan { background: var(--ai-kode); color: var(--ai-redup); }
.mp227-an-h { display: flex; align-items: center; gap: 7px; margin-bottom: 4px; color: var(--ai-teks); } .mp227-an-h > i { color: var(--ai-aksen); }
.mp227-an-s { margin: 8px 0 4px; font-size: .7rem; font-weight: 700; color: var(--ai-redup); text-transform: uppercase; letter-spacing: .04em; }
.mp227-tm { list-style: none; margin: 0; padding: 0; display: grid; gap: 5px; }
.mp227-tm li { display: flex; gap: 8px; align-items: flex-start; padding: 6px 8px; border-radius: 8px; background: var(--ai-latar); border: 1px solid var(--f-garis, #D3DBE6); }
.mp227-tm li > div { min-width: 0; } .mp227-tm li > div > div { color: var(--ai-redup); font-size: .78rem; margin-top: 1px; }
.mp227-tm .tg { flex: none; font-size: .62rem; font-weight: 700; text-transform: uppercase; padding: 1px 6px; border-radius: 999px; background: var(--ai-kode); color: var(--ai-teks); margin-top: 2px; }
.mp227-tm li.tinggi .tg { background: #E3343F; color: #FFFFFF; } .mp227-tm li.sedang .tg { background: #F28C28; color: #1A1203; } .mp227-tm li.rendah .tg { background: #2E9E5B; color: #FFFFFF; }
.mp227-sr { padding: 7px 9px; border-radius: 9px; border: 1px solid var(--f-garis, #D3DBE6); background: var(--f-kartu, #fff); margin-bottom: 6px; }
.mp227-sr.selesai { background: var(--ai-ok-bg); }
.mp227-sr .t { display: flex; gap: 6px; flex-wrap: wrap; align-items: baseline; }
.mp227-sr .ak { font-size: .64rem; font-weight: 700; padding: 0 6px; border-radius: 999px; background: var(--ai-kode); color: var(--ai-teks); }
.mp227-sr .ak.tulis { background: var(--ai-warn-bg); color: var(--ai-warn-tk); }
.mp227-sr .d { color: var(--ai-redup); font-size: .78rem; margin-top: 2px; } .mp227-sr .d i { color: var(--ai-aksen); }
/* form */
.mp227-ai-f { border-top: 1px solid var(--f-garis, #D3DBE6); padding: 8px 10px 10px; background: var(--f-kartu, #fff); color: var(--ai-teks); display: grid; gap: 6px; flex: none; }
.mp227-ai-f .form-check-label, .mp227-ai-f label { color: var(--ai-teks); }
.mp227-ai-f textarea { box-sizing: border-box; font: inherit; width: 100%; resize: none; border: 1px solid var(--f-garis, #D3DBE6); border-radius: 9px; padding: 7px 9px; font-size: .86rem; background: var(--f-kartu, #fff); color: var(--ai-teks); }
.mp227-ai-f textarea::placeholder { color: var(--ai-redup); opacity: 1; }
.mp227-ai-f textarea:focus { outline: 2px solid var(--ai-aksen); outline-offset: 0; border-color: var(--ai-aksen); }
.mp227-ai-f textarea:disabled { background: var(--ai-latar); color: var(--ai-redup); }
.mp227-ngetik { display: flex; gap: 4px; padding: 4px 2px; } .mp227-ngetik span { width: 7px; height: 7px; border-radius: 50%; background: var(--ai-aksen); animation: mp227t 1s infinite; }
.mp227-ngetik span:nth-child(2) { animation-delay: .15s; } .mp227-ngetik span:nth-child(3) { animation-delay: .3s; }
@keyframes mp227t { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-3px); } }
@media (prefers-reduced-motion: reduce) { .mp227-ngetik span { animation: none; } }
/* setelan penyedia (dialog Admin) */
.mp227-pvs { display: grid; gap: 8px; }
.mp227-pv { border: 1px solid var(--f-line, #E1E7F0); border-radius: 10px; padding: 8px 10px; background: var(--f-bg, #fff); color: var(--f-ink, #14233A); }
.mp227-pv .pv-h { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-bottom: 6px; }
.mp227-pv .pv-g { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px 8px; }
.mp227-pv .pv-g label { display: block; font-size: .7rem; font-weight: 600; color: var(--f-muted, #61708A); margin-bottom: 1px; }
.mp227-pv .pv-url { grid-column: 1 / -1; }
@media (max-width: 767.98px) { .mp227-pv .pv-g { grid-template-columns: 1fr; } }
.mp227-tag { display: inline-block; font-size: .66rem; font-weight: 700; padding: 1px 7px; border-radius: 999px; background: #E8EEF7; color: #0B1F3A; }
.mp227-tag.abu { background: #EEF1F5; color: #44546B; }
html[data-tema="gelap"] .mp227-tag { background: #1D3350; color: #E8EEF7; } html[data-tema="gelap"] .mp227-tag.abu { background: #22344A; color: #B4C2D4; }
/* [2.2.10] hasil uji penyedia & peringatan key */
.mp227-pvw { font-size: .74rem; color: #8A1A20; background: #FDECEC; border-radius: 6px; padding: 3px 7px; margin-bottom: 6px; }
html[data-tema="gelap"] .mp227-pvw { color: #FFC9CC; background: #3A1518; }
.mp227-uj ul { list-style: none; padding: 0; margin: 6px 0; display: grid; gap: 4px; }
.mp227-uj li { display: block; padding: 4px 7px; border-radius: 6px; background: rgba(127, 127, 127, .14); border: 1px solid rgba(127, 127, 127, .25); color: inherit; line-height: 1.4; }
.mp227-uj li i { margin-right: 5px; } .mp227-uj li.ok i { color: #1E7D47; } .mp227-uj li.gagal i { color: #C0262F; }
.mp227-uj li small { display: block; color: inherit; font-size: .9em; margin-top: 1px; overflow-wrap: anywhere; }
html[data-tema="gelap"] .mp227-uj li.ok i { color: #9FE0B8; } html[data-tema="gelap"] .mp227-uj li.gagal i { color: #FF9AA0; }
@media print { .mp227-fab, .mp227-ai { display: none !important; } }

/* MP230 — Verifikasi Tagihan (2.3.0): menu Keuangan & Bayar + tab Verifikasi AI di checklist */
.mp230-bd { display: inline-flex; align-items: center; gap: 5px; padding: 3px 9px; border-radius: 999px; font-size: .74rem; font-weight: 700; white-space: nowrap; color: var(--p); background: color-mix(in srgb, var(--p) 11%, transparent); border: 1px solid color-mix(in srgb, var(--p) 32%, transparent); }
.mp230-bd.k { padding: 1px 7px; font-size: .68rem; margin-top: 4px; }
html[data-tema="gelap"] .mp230-bd, html[data-tema="gelap"] .mp230-n { color: color-mix(in srgb, var(--p) 55%, #fff); }
.mp219-aksi button.v { border-color: color-mix(in srgb, #5B4BC4 45%, transparent); }
.mp219-aksi button.v i { color: #5B4BC4; }
html[data-tema="gelap"] .mp219-aksi button.v i { color: #A99BFF; }
.mp230-tn { display: inline-block; min-width: 18px; margin-left: 6px; padding: 0 6px; border-radius: 999px; background: #C0262D; color: #fff; font-size: .7rem; line-height: 18px; text-align: center; }
.mp230-dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; background: var(--p); margin-left: 6px; vertical-align: middle; }
.mp230-muted { color: var(--f-muted); font-size: .8rem; }
.mp230-dash { display: flex; flex-direction: column; gap: 12px; }
.mp230-kepala { display: flex; justify-content: space-between; gap: 16px; padding: 16px 18px; align-items: flex-start; flex-wrap: wrap; }
.mp230-kp-t { display: flex; gap: 12px; flex: 1 1 420px; min-width: 0; }
.mp230-kp-t h5 { margin: 0 0 4px; font-weight: 800; color: var(--f-ink); }
.mp230-kp-t h5 small { font-size: .68rem; font-weight: 700; color: #5B4BC4; background: color-mix(in srgb, #5B4BC4 12%, transparent); border-radius: 999px; padding: 2px 8px; margin-left: 6px; vertical-align: middle; }
.mp230-kp-t p { margin: 0 0 8px; color: var(--f-muted); font-size: .84rem; max-width: 820px; }
.mp230-ik { flex: 0 0 auto; width: 42px; height: 42px; border-radius: 12px; display: grid; place-items: center; background: #0B2B54; color: #fff; font-size: 1.1rem; }
.mp230-meta { display: flex; flex-wrap: wrap; gap: 6px 14px; font-size: .78rem; color: var(--f-ink); }
.mp230-meta i { color: var(--w-biru); margin-right: 5px; }
.mp230-kp-a { display: flex; gap: 8px; flex-wrap: wrap; }
.mp230-kpi { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.mp230-k { text-align: left; background: var(--f-bg); border: 1px solid var(--f-line); border-left: 4px solid var(--w); border-radius: 12px; padding: 10px 14px; color: var(--f-ink); display: flex; flex-direction: column; gap: 2px; box-shadow: var(--f-shadow); }
.mp230-k span { font-size: .78rem; font-weight: 700; color: var(--f-muted); }
.mp230-k span i { color: var(--w); margin-right: 6px; }
.mp230-k b { font-size: 1.5rem; line-height: 1.1; }
.mp230-k small { font-size: .72rem; color: var(--f-muted); }
.mp230-k.on, .mp230-k:hover { border-color: var(--w); background: color-mix(in srgb, var(--w) 7%, var(--f-bg)); }
.mp230-ns { margin-top: 4px; display: flex; gap: 4px; flex-wrap: wrap; font-size: .72rem; color: var(--f-muted); }
.mp230-n { font-size: .7rem; font-weight: 700; color: var(--p); background: color-mix(in srgb, var(--p) 10%, transparent); border-radius: 6px; padding: 0 6px; }
.mp230-tu { font-size: .78rem; }
.mp230-tb .mp230-bd { white-space: normal; max-width: 100%; }
.mp230-tb td { vertical-align: top; }
.mp230-tu div + div { margin-top: 2px; }
.mp230-pn { padding: 0 0 12px; }
